def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Merge overlapping or touching intervals.

    Touching means next_start <= previous_end.
    Adjacent non-overlapping integer ranges like (1,2) and (3,4) are NOT merged.
    """
    if not intervals:
        return []

    # Validate intervals
    for interval in intervals:
        if not isinstance(interval, tuple) or len(interval) != 2:
            raise ValueError(f"Invalid interval shape: {interval}")
        start, end = interval
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError(f"Interval endpoints must be integers: {interval}")
        if start > end:
            raise ValueError(f"Invalid interval, start > end: {interval}")

    # Sort by start, then by end
    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))

    merged: list[tuple[int, int]] = []
    for start, end in sorted_intervals:
        if not merged:
            merged.append((start, end))
        else:
            prev_start, prev_end = merged[-1]
            # Merge if overlapping or touching: next_start <= previous_end
            if start <= prev_end:
                # Update the end of the last merged interval
                merged[-1] = (prev_start, max(prev_end, end))
            else:
                merged.append((start, end))

    return merged
